        __state = S_DONE;  // until a yield sets where to resume
        r.emplace(::tpyapp::main::make_tok(7, v));
        __sub_0.emplace(std::move(::tpystd::asyncio::sleep(static_cast<double>(0))));
        __state = S_RESUME_0;
